theorem unpair₁ {n f} (hf : @Primrec' n f) : @Primrec' n fun v => (f v).unpair.1  := by
  refine (if_lt (sub.comp₂ _ hf (mul.comp₂ _ _ _)) _ (sub.comp₂ _ hf (mul.comp₂ _ _ _)) _).of_eq (fun v => ?_);
  simp [Nat.unpair]; split_ifs <;> rfl</IMPROVED>
